### Ran Playwright code
```js
await page.evaluate('()=>{window.__ccClicks=0;const original=AudioContext.prototype.createOscillator;AudioContext.prototype.createOscillator=function(...args){window.__ccClicks++;return original.apply(this,args);};if(!Array.from(document.querySelectorAll(\'button\')).some(b=>b.textContent===\'Sound off\'))throw Error(\'Sound not muted by default\');return {mutedByDefault:true};}');
```

